[TFMPageType('PendingRegistrations', "PendingRegistrations")]
class TFMPagePendingRegistrationsConfiguration extends TFMListPageConfiguration
{
    boolean     allRegistrationTypes;
    boolean     deleteRegistrationEnabled;
    boolean     postAllRegistrationsEnabled;
    TFMPageTitleString				deleteRegistrationTitle;
    TFMPageTitleString				postAllRegistrationsTitle;
    boolean     resubmitRegistrationEnabled;
    TFMPageTitleString				resubmitRegistrationTitle;
    boolean     viewErrorMessageEnabled;
    TFMPageTitleString				viewErrorMessageTitle;
    TFMListId	listId;

}

Method.Source:
[TFMPageConfigurationAttributeAttribute(false,'','allRegistrationTypes',true)]
public boolean parmAllRegistrationTypes(boolean _allRegistrationTypes = allRegistrationTypes)
{
    allRegistrationTypes = _allRegistrationTypes;
    return allRegistrationTypes;
}

[TFMPageConfigurationAttributeAttribute(classStr(TFMListPendingAdhocRegistrationsList),'list','',true)]
public TFMListId parmListId(TFMListId _listId = listId)
{
    TFMList			listCls;
    listId = _listId;
    if (className2Id(listId))
    {
        listCls = new SysDictClass(className2Id(listId)).makeObject();
        listId = listCls.parmListName();
    }
    return listId;
}

[TFMPageConfigurationAttributeAttribute('DeleteRegistration','deleteRegistration','title',true),TFMPageAction]
public TFMPageTitleString parmDeleteRegistrationTitle(TFMPageTitleString _viewRegistrationTitle = deleteRegistrationTitle)
{
    deleteRegistrationTitle = _viewRegistrationTitle;
    return deleteRegistrationTitle;
}

[TFMPageConfigurationAttributeAttribute(true,'deleteRegistration','enabled',true),TFMPageAction]
public boolean parmDeleteRegistrationEnabled(boolean _viewRegistrationsEnabled = deleteRegistrationEnabled)
{
    deleteRegistrationEnabled = _viewRegistrationsEnabled;
    return deleteRegistrationEnabled;
}

